-- 角色备注与名称唯一约束；不改名、不合并、不删除任何存量角色。
-- 同名 preflight 失败时停止，待管理员明确处理冲突后再续跑。

-- @step preflight_role_name_uniqueness
-- @check SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM sys_role GROUP BY name HAVING COUNT(*) > 1) THEN 1 ELSE 0 END AS complete;
UPDATE sys_role SET name = name WHERE 1 = 0;

-- @step add_role_remark
-- @replaces-check 002_access/create_sys_role
-- @check SELECT CASE WHEN EXISTS (SELECT 1 FROM INFORMATION_SCHEMA.TABLES WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME='sys_role' AND TABLE_TYPE='BASE TABLE' AND ENGINE='InnoDB' AND TABLE_COLLATION='utf8mb4_0900_ai_ci') AND (SELECT COUNT(*) FROM INFORMATION_SCHEMA.COLUMNS WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME='sys_role')=8 AND (SELECT COUNT(*) FROM INFORMATION_SCHEMA.COLUMNS WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME='sys_role' AND ((COLUMN_NAME='id' AND COLUMN_TYPE='bigint unsigned' AND IS_NULLABLE='NO' AND COLUMN_DEFAULT IS NULL AND EXTRA='auto_increment') OR (COLUMN_NAME='code' AND COLUMN_TYPE='varchar(64)' AND IS_NULLABLE='NO' AND COLUMN_DEFAULT IS NULL AND EXTRA='') OR (COLUMN_NAME='name' AND COLUMN_TYPE='varchar(128)' AND IS_NULLABLE='NO' AND COLUMN_DEFAULT IS NULL AND EXTRA='') OR (COLUMN_NAME='remark' AND COLUMN_TYPE='varchar(500)' AND IS_NULLABLE='YES' AND COLUMN_DEFAULT IS NULL AND EXTRA='') OR (COLUMN_NAME='is_system' AND COLUMN_TYPE='tinyint' AND IS_NULLABLE='NO' AND COLUMN_DEFAULT='0' AND EXTRA='') OR (COLUMN_NAME='status' AND COLUMN_TYPE='tinyint' AND IS_NULLABLE='NO' AND COLUMN_DEFAULT='1' AND EXTRA='') OR (COLUMN_NAME='created_at' AND COLUMN_TYPE='datetime(3)' AND IS_NULLABLE='NO' AND COLUMN_DEFAULT='CURRENT_TIMESTAMP(3)' AND EXTRA='DEFAULT_GENERATED') OR (COLUMN_NAME='updated_at' AND COLUMN_TYPE='datetime(3)' AND IS_NULLABLE='NO' AND COLUMN_DEFAULT='CURRENT_TIMESTAMP(3)' AND EXTRA='DEFAULT_GENERATED on update CURRENT_TIMESTAMP(3)')))=8 AND (SELECT COUNT(*) FROM INFORMATION_SCHEMA.STATISTICS WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME='sys_role' AND INDEX_NAME IN ('PRIMARY','uk_sys_role_code','idx_sys_role_status'))=3 AND (SELECT COUNT(*) FROM INFORMATION_SCHEMA.STATISTICS WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME='sys_role' AND ((INDEX_NAME='PRIMARY' AND NON_UNIQUE=0 AND SEQ_IN_INDEX=1 AND COLUMN_NAME='id' AND INDEX_TYPE='BTREE' AND SUB_PART IS NULL) OR (INDEX_NAME='uk_sys_role_code' AND NON_UNIQUE=0 AND SEQ_IN_INDEX=1 AND COLUMN_NAME='code' AND INDEX_TYPE='BTREE' AND SUB_PART IS NULL) OR (INDEX_NAME='idx_sys_role_status' AND NON_UNIQUE=1 AND SEQ_IN_INDEX=1 AND COLUMN_NAME='status' AND INDEX_TYPE='BTREE' AND SUB_PART IS NULL)))=3 AND (SELECT COUNT(*) FROM INFORMATION_SCHEMA.REFERENTIAL_CONSTRAINTS WHERE CONSTRAINT_SCHEMA=DATABASE() AND TABLE_NAME='sys_role')=0 THEN 1 ELSE 0 END AS complete;
ALTER TABLE `sys_role` ADD COLUMN `remark` VARCHAR(500) NULL COMMENT '角色备注' AFTER `name`;

-- @step add_unique_role_name
-- @check SELECT CASE WHEN (SELECT COUNT(*) FROM INFORMATION_SCHEMA.STATISTICS WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME='sys_role' AND INDEX_NAME='uk_sys_role_name')=1 AND (SELECT COUNT(*) FROM INFORMATION_SCHEMA.STATISTICS WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME='sys_role' AND INDEX_NAME='uk_sys_role_name' AND NON_UNIQUE=0 AND SEQ_IN_INDEX=1 AND COLUMN_NAME='name' AND INDEX_TYPE='BTREE' AND SUB_PART IS NULL)=1 THEN 1 ELSE 0 END AS complete;
CREATE UNIQUE INDEX `uk_sys_role_name` ON `sys_role` (`name`);
